--====== Helper functions =========--
local function csm(time)
	local start_time = GetRunningTime()
	while GetRunningTime() - start_time <= time do
	end
end

local remainder_fx, remainder_fy = 0, 0
local function MoveMouseRelativeFractional(x, y)
	x = remainder_fx + x
	y = remainder_fy + y
	local xi = math.floor(x + 0.5)
	local yi = math.floor(y + 0.5)
	remainder_fx = x - xi
	remainder_fy = y - yi
	MoveMouseRelative(xi, yi)
end

