--====== Run a recoil pattern =========--
local function run_pattern(data)
	remainder_fx = 0
	remainder_fy = 0
	csm(data.init)
	if IsMouseButtonPressed(click) then
		repeat
			for i = 1, #data.steps do
				local s = data.steps[i]
				local t = s[1]
				if t == 0 then
					csm(s[2])
				elseif t == 1 then
					if not IsMouseButtonPressed(1) then break end
				else
					MoveMouseRelativeFractional(s[2] * kava * SensSetting, s[3] * kava * SensSetting)
				end
			end
		until not IsMouseButtonPressed(1)
	end
end

--====== Weapon binding lookup (direct refs to local vars) =========--
local function check_mouse_bind(arg)
	if arg == AKM then return "AKM" end
	if arg == BERRYL then return "BERRYL" end
	if arg == M416 then return "M416" end
	if arg == SCAR_L then return "SCAR_L" end
	if arg == AUG then return "AUG" end
	if arg == GROZA then return "GROZA" end
	if arg == ACE32 then return "ACE32" end
	if arg == FAMAS then return "FAMAS" end
	if arg == BIZON then return "BIZON" end
	if arg == TOMMY then return "TOMMY" end
	if arg == UMP45 then return "UMP45" end
	if arg == MP5K then return "MP5K" end
	if arg == P90 then return "P90" end
	return nil
end

local function check_kb_bind(arg)
	if arg == AKM_Keyboard then return "AKM" end
	if arg == BERRYL_Keyboard then return "BERRYL" end
	if arg == M416_Keyboard then return "M416" end
	if arg == SCAR_L_Keyboard then return "SCAR_L" end
	if arg == AUG_Keyboard then return "AUG" end
	if arg == GROZA_Keyboard then return "GROZA" end
	if arg == ACE32_Keyboard then return "ACE32" end
	if arg == FAMAS_Keyboard then return "FAMAS" end
	if arg == BIZON_Keyboard then return "BIZON" end
	if arg == TOMMY_Keyboard then return "TOMMY" end
	if arg == UMP45_Keyboard then return "UMP45" end
	if arg == MP5K_Keyboard then return "MP5K" end
	if arg == P90_Keyboard then return "P90" end
	return nil
end

local function identify_weapon(weapon_arg)
	if weapon_arg == AKM or weapon_arg == AKM_Keyboard then return "AKM" end
	if weapon_arg == BERRYL or weapon_arg == BERRYL_Keyboard then return "BERRYL" end
	if weapon_arg == M416 or weapon_arg == M416_Keyboard then return "M416" end
	if weapon_arg == SCAR_L or weapon_arg == SCAR_L_Keyboard then return "SCAR_L" end
	if weapon_arg == AUG or weapon_arg == AUG_Keyboard then return "AUG" end
	if weapon_arg == GROZA or weapon_arg == GROZA_Keyboard then return "GROZA" end
	if weapon_arg == ACE32 or weapon_arg == ACE32_Keyboard then return "ACE32" end
	if weapon_arg == FAMAS or weapon_arg == FAMAS_Keyboard then return "FAMAS" end
	if weapon_arg == BIZON or weapon_arg == BIZON_Keyboard then return "BIZON" end
	if weapon_arg == TOMMY or weapon_arg == TOMMY_Keyboard then return "TOMMY" end
	if weapon_arg == UMP45 or weapon_arg == UMP45_Keyboard then return "UMP45" end
	if weapon_arg == MP5K or weapon_arg == MP5K_Keyboard then return "MP5K" end
	if weapon_arg == P90 or weapon_arg == P90_Keyboard then return "P90" end
	return nil
end

--====== Weapon toggle helper =========--
local weapon_log_suffix = {
	AKM = {off = "-AKM", on = "-AKM", scroll = true},
	BERRYL = {off = "-BERRYL", on = "-BERRYL", scroll = true},
	M416 = {off = "-M416", on = "-M416", scroll = true},
	SCAR_L = {off = "-SCAR_L", on = "-SCAR_L", scroll = true},
	AUG = {off = ".Com-AUG", on = ".Com-AUG", scroll = true},
	GROZA = {off = "-GROZA", on = "-GROZA", scroll = true},
	ACE32 = {off = "-ACE32", on = "-ACE32", scroll = true},
	FAMAS = {off = "-FAMAS", on = "-FAMAS", scroll = true},
	BIZON = {off = "-BIZON", on = "-BIZON", scroll = true},
	TOMMY = {off = "-TOMMY", on = "-TOMMY", scroll = true},
	UMP45 = {off = "-UMP45", on = "-UMP45", scroll = true},
	MP5K = {off = "-MP5K", on = "-MP5K", scroll = true},
	P90 = {off = ".Com-P90", on = ".Com-P90", scroll = true},
}

local function toggle_weapon(wname, arg)
	recoil = not recoil
	weapon = arg
	local log = weapon_log_suffix[wname]
	if recoil then
		OutputLogMessage("ON-NoRecoil-kava" .. log.on .. "\n")
		if log.scroll and not IsKeyLockOn("scrolllock") then
			PressAndReleaseKey("scrolllock")
		end
	else
		OutputLogMessage("OFF-kava" .. log.off .. "\n")
		if log.scroll and IsKeyLockOn("scrolllock") then
			PressAndReleaseKey("scrolllock")
		end
	end
end

--====== OnEvent =========--
function OnEvent(event, arg)
	-- MACRO_OFF toggle (special: always logs OFF, no scrolllock)
	if (event == "MOUSE_BUTTON_PRESSED" and arg == MACRO_OFF) or (event == "G_PRESSED" and arg == MACRO_OFF_Keyboard) then
		recoil = not recoil
		weapon = arg
		OutputLogMessage("OFF-kava\n")
		return
	end

	-- Weapon toggle on key press
	local wname = nil
	if event == "MOUSE_BUTTON_PRESSED" then
		wname = check_mouse_bind(arg)
	elseif event == "G_PRESSED" then
		wname = check_kb_bind(arg)
	end
	if wname then
		toggle_weapon(wname, arg)
		return
	end

	-- Run recoil pattern if active
	if recoil and weapon then
		wname = identify_weapon(weapon)
		if wname then
			local fb = fn_base[wname]
			local caps = IsKeyLockOn("capslock") and 4 or 0
			local ctrl = IsModifierPressed("lctrl") and 2 or 0
			local shift = IsModifierPressed("lshift") and 1 or 0
			local code = caps + ctrl + shift
			local disp = weapon_dispatch[wname][code]
			if disp then
				kava = kava_values[disp[2]] or 1
				local pat = patterns[fb] and patterns[fb][disp[1]]
				if pat then
					run_pattern(pat)
				end
			end
		end
	end
end
